-- READ-ONLY aggregate; 2018 Q2-Q4 only, Q1 2018 excluded.
WITH c AS (SELECT CASE WHEN o.dateTime<1530403200 THEN '2018-Q2' WHEN o.dateTime<1538352000 THEN '2018-Q3' ELSE '2018-Q4' END AS utc_quarter,o.usUnits AS ou,w.usUnits AS wu,o.interval AS oi,w.interval AS wi,o.`soilMoist4` AS old_soilMoist4,w.`soilMoist4` AS wh_soilMoist4 FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1522540800 AND o.dateTime<1546300800 AND r.dateTime IS NULL) SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilMoist4' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilMoist4 IS NOT NULL) AS old_nonnull,SUM(wh_soilMoist4 IS NOT NULL) AS wh_nonnull,SUM(old_soilMoist4 IS NOT NULL AND wh_soilMoist4 IS NOT NULL AND old_soilMoist4<=>wh_soilMoist4) AS paired_equal,SUM(old_soilMoist4 IS NOT NULL AND wh_soilMoist4 IS NOT NULL AND NOT(old_soilMoist4<=>wh_soilMoist4)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi ORDER BY utc_quarter,old_interval,wh_interval;
